// Generates src/abi/{campaign,factory}.ts from the Foundry build output.
// Run `forge build` in ../contracts first. Never edit the generated files by hand.
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const appDir = join(dirname(fileURLToPath(import.meta.url)), '..')
const outDir = join(appDir, '..', 'contracts', 'out')

const targets = [
  { contract: 'Campaign', file: 'campaign.ts', name: 'campaignAbi' },
  { contract: 'CampaignFactory', file: 'factory.ts', name: 'factoryAbi' },
]

for (const { contract, file, name } of targets) {
  const artifact = join(outDir, `${contract}.sol`, `${contract}.json`)
  let abi
  try {
    abi = JSON.parse(readFileSync(artifact, 'utf8')).abi
  } catch (err) {
    console.error(`Cannot read ${artifact}. Run \`forge build\` in contracts/ first.`)
    throw err
  }
  if (!Array.isArray(abi) || abi.length === 0) throw new Error(`${artifact} has no ABI`)
  const body =
    `// Generated by scripts/gen-abis.mjs from contracts/out/${contract}.sol/${contract}.json. Do not edit.\n` +
    `export const ${name} = ${JSON.stringify(abi, null, 2)} as const\n`
  writeFileSync(join(appDir, 'src', 'abi', file), body)
  console.log(`wrote src/abi/${file} (${abi.length} entries)`)
}
